import pandas as pd
file_path = '/data/monthly_expense_ledger.xlsx'
raw = pd.read_excel(file_path, sheet_name='Expense Ledger', header=None)

monthly_sums = {}
for i in range(raw.shape[0]):
    row = raw.iloc[i]
    trans_id = row[0]
    date_val = row[1]
    amount = row[7]
    if isinstance(trans_id, str) and trans_id.startswith('EXP-'):
        try:
            dt = pd.to_datetime(date_val)
        except:
            continue
        if dt.year == 2025 and 4 <= dt.month <= 9:
            month = dt.strftime('%Y-%m')
            amt = float(amount) if pd.notna(amount) else 0
            monthly_sums.setdefault(month, 0)
            monthly_sums[month] += amt

for k in sorted(monthly_sums):
    print(k, monthly_sums[k])
print("Grand sum", sum(monthly_sums.values()))

